package nibby;

import java.util.Arrays;

/**
 * Nibby Nibble, native Java version.
 *
 * <p>The rules and every timing come from the analysis of the original 68000
 * program (see the emulated version in emu/, which ports it routine by
 * routine). Here the game is written directly in Java: three layers (maze,
 * hardware-like sprites, snake body) are composed into a 320x262 frame with
 * a 32-colour palette, which is all the fades, the copper rainbows and the
 * death palette need.
 *
 * <p>The game logic runs in its own thread and calls {@link #frame()} to wait
 * for the next 50 Hz frame, like the original waited for the vertical blank.
 */
public final class Game implements Runnable {
    public static final int WIDTH = 320, HEIGHT = 262;
    static final int FIELD_H = 224;            // maze: 14 rows of 16 lines
    static final int STATUS_Y = 225;           // status bar: 37 lines
    static final int BANNER_Y = 100;           // "STAGE nn" / "GAME OVER"

    static final int RIGHT = 1, LEFT = 2, DOWN = 4, UP = 8;
    static final int HISTORY = 600;
    static final int MAX_SEGMENTS = 91;
    static final String CHEAT = "THE RONCLER GANG";
    static final int[] ANIM = {0, 1, 2, 1};    // animation frame sequence

    // ---------------------------------------------------------------- assets
    private final Bitmap title = Assets.bitmap("title.png");
    private final int[] titlePalette = Assets.palette("title.png", 16);
    private final Bitmap statusBarImage = Assets.bitmap("statusbar.png");
    private final int[] statusPalette = Assets.palette("statusbar.png", 8);
    private final Bitmap stageImage = Assets.bitmap("stage.png");
    private final Bitmap gameOverImage = Assets.bitmap("gameover.png");
    private final Bitmap digits = Assets.bitmap("digits.png");
    private final int[] rainbow = Assets.colours(Assets.lines("rainbow.txt").get(0));
    private final Bitmap[][] head = new Bitmap[4][3];                 // right, left, down, up
    private final Bitmap[] tail1H = new Bitmap[3], tail1V = new Bitmap[3];
    private final Bitmap[] tail2H = new Bitmap[3], tail2V = new Bitmap[3];
    private final Bitmap signature = Assets.bitmap("sprites/signature.png");
    private final Bitmap[] bodyH = new Bitmap[3], bodyV = new Bitmap[3];
    private final Bitmap bodyMask = Assets.bitmap("shapes/body_mask.png");
    private final Bitmap[] burn = new Bitmap[7], burnMask = new Bitmap[7];
    private final Bitmap[] explosion = new Bitmap[13];
    private final Bitmap block = new Bitmap(16, 16);
    private final Level[] levels = new Level[10];

    private static final int[] SNAKE_COLOURS = {0xe00, 0xa00, 0x333};
    private static final int[] HEAD_COLOURS = {0xeca, 0x0dd, 0x70f, 0xfe0, 0xe00, 0xa00, 0x333};
    private static final int[] BANNER_GRADIENT = {0xa80, 0xda0, 0xfd0, 0xff0, 0xfd0, 0xda0, 0xa80};

    private final ModPlayer music = new ModPlayer(Assets.bytes("nib-rsi.mod"));
    private final Input input;
    private final boolean trainerLives, trainerTime;

    // ---------------------------------------------------------------- display state
    enum Screen { BLACK, TITLE, STAGE, GAME, FADE, DEATH, GAME_OVER }

    private volatile Screen screen = Screen.BLACK;
    private final int[] palette = new int[32];       // game palette (fades change it)
    private final int[] deathPalette = new int[32];
    private final int[] titleRainbow = new int[180];
    private final int[] statusRainbow = {0x00f, 0x0f0, 0xf00, 0x00f, 0xf00, 0x0f0, 0x00f};  // copper list defaults
    private final Bitmap maze = new Bitmap(WIDTH, FIELD_H);   // colours 0-7
    private final Bitmap body = new Bitmap(WIDTH, FIELD_H);   // colours 8-11, in front of the sprites
    private final Bitmap status = new Bitmap(WIDTH, 37);
    private final Bitmap stage = new Bitmap(WIDTH, 7);
    private int flashFrames, flashValue;

    /** A sprite on screen (null image: hidden). */
    private static final class Sprite {
        Bitmap image;
        int x, y, colourBase;

        void set(Bitmap image, int x, int y) {
            this.image = image;
            this.x = x;
            this.y = y;
        }
    }

    private final Sprite headSprite = new Sprite(), tailSprite1 = new Sprite(), tailSprite2 = new Sprite();
    private final Sprite signatureSprite = new Sprite();
    private boolean collision;               // head over a body pixel of colour 3, last frame
    /** The status bar is drawn by the copper list generated by the game loop: not before its first frame. */
    private boolean statusVisible;

    // ---------------------------------------------------------------- game state
    private char key, lastKey;
    private int cheatPos;
    private boolean cheat;                   // infinite lives (and frozen timer)
    private Level level;
    private int levelNumber;
    private int rainbowIndex;
    private int lives, time, score;
    private boolean timeOut, timerOn;
    private int timerFrames;
    private int wantDir, x, y, dir;          // x in 2-pixel units, y in lines
    private boolean dirChanged;
    private int segments, growCount, growA, growB;
    private final char[][] dots = new char[Level.ROWS][Level.COLS];
    private int dotsLeft;
    private boolean levelDone;
    private Bitmap[] headAnim;
    private Bitmap headImage;
    private int animDelay, animFrame;
    private final int[] histX = new int[HISTORY], histY = new int[HISTORY];
    private int histIdx;
    /** Body segments: built this frame, shown next frame (the original blits one frame late). */
    private int[] builtBody = new int[0], shownBody = new int[0];

    private enum Outcome { ESCAPE, COMPLETE, DEATH }

    public Game(Input input, boolean trainerLives, boolean trainerTime) {
        this.input = input;
        this.trainerLives = trainerLives;
        this.trainerTime = trainerTime;
        String[] dirs = {"right", "left", "down", "up"};
        for (int d = 0; d < 4; d++)
            for (int f = 0; f < 3; f++) head[d][f] = Assets.bitmap("sprites/head_" + dirs[d] + "_" + f + ".png");
        for (int f = 0; f < 3; f++) {
            tail1H[f] = Assets.bitmap("sprites/tail1_h_" + f + ".png");
            tail1V[f] = Assets.bitmap("sprites/tail1_v_" + f + ".png");
            tail2H[f] = Assets.bitmap("sprites/tail2_h_" + f + ".png");
            tail2V[f] = Assets.bitmap("sprites/tail2_v_" + f + ".png");
            bodyH[f] = Assets.bitmap("shapes/body_h_" + f + ".png");
            bodyV[f] = Assets.bitmap("shapes/body_v_" + f + ".png");
        }
        for (int i = 0; i < 7; i++) {
            burn[i] = Assets.bitmap("shapes/burn_" + i + ".png");
            burnMask[i] = Assets.bitmap("shapes/burn_" + i + "_mask.png");
        }
        String[] seq = Assets.lines("shapes/explosion.txt").get(0).trim().split("\\s+");
        for (int i = 0; i < 13; i++) explosion[i] = Assets.bitmap("shapes/explosion_" + seq[i] + ".png");
        Arrays.fill(block.px, (byte) 1);
        for (int i = 0; i < 10; i++) levels[i] = Level.load(i + 1);
        tailSprite1.colourBase = tailSprite2.colourBase = 24;
        signatureSprite.colourBase = 28;
        headSprite.colourBase = 16;
        status.paste(statusBarImage, 0, 0);     // never redrawn afterwards, like the original
        music.setTickHook(c -> {
            if (c == 1) printScore();
            else printTime();
        });
    }

    public ModPlayer music() {
        return music;
    }

    // ================================================================ frame sync

    private final java.util.concurrent.Semaphore toGame = new java.util.concurrent.Semaphore(0);
    private final java.util.concurrent.Semaphore toHost = new java.util.concurrent.Semaphore(0);
    private volatile Throwable crash;

    /** Starts the game thread. */
    public void start() {
        Thread t = new Thread(() -> {
            toGame.acquireUninterruptibly();
            try {
                run();
            } catch (Throwable e) {
                crash = e;
            } finally {
                toHost.release();
            }
        }, "game");
        t.setDaemon(true);
        t.start();
    }

    /** Host side: runs one 50 Hz frame of the game. */
    public void step(Character typed) {
        if (typed != null) key = typed;
        // screens without a game loop get their music from the (copper) interrupt
        if (screen == Screen.TITLE || screen == Screen.STAGE || screen == Screen.DEATH || screen == Screen.GAME_OVER)
            tickMusic();
        toGame.release();
        toHost.acquireUninterruptibly();
        if (crash != null) throw new IllegalStateException("game crashed", crash);
    }

    /** Game side: waits for the next frame. */
    private void frame() {
        toHost.release();
        toGame.acquireUninterruptibly();
    }

    // ================================================================ flow

    @Override
    public void run() {
        signatureSprite.set(signature, 288, 213);
        while (true) {
            titleScreen();
            score = 0;
            printScore();
            timerOn = false;
            lives = 3;
            levelNumber = 1;
            boolean playing = true;
            while (playing) {
                levelIntro();
                startLevel();
                switch (mainLoop()) {
                    case ESCAPE -> {
                        fadeOut();
                        playing = false;
                    }
                    case COMPLETE -> {
                        fadeOut();
                        if (++levelNumber == 11) levelNumber = 1;
                    }
                    case DEATH -> playing = death();
                }
            }
        }
    }

    /** Title screen: rainbow, cheat code, fire to start. */
    private void titleScreen() {
        key = 0;
        screen = Screen.TITLE;
        while (true) {
            frame();
            int a = nextRainbow();
            for (int i = 0; i < titleRainbow.length; i++, a = (a + 1) % rainbow.length) titleRainbow[i] = rainbow[a];
            char k = key;
            if (k != 0 && k != lastKey) {
                lastKey = k;
                cheatPos = k == CHEAT.charAt(cheatPos) ? cheatPos + 1 : 0;
                if (cheatPos == CHEAT.length()) {
                    flashFrames = 12;
                    while (flashFrames > 0) frame();
                    cheat = true;
                    cheatPos = 0;
                    return;
                }
            }
            if (input.fire) break;
        }
        while (input.fire) frame();
    }

    private int nextRainbow() {
        rainbowIndex = (rainbowIndex + 1) % rainbow.length;
        return rainbowIndex;
    }

    /** "STAGE nn": waits for fire. */
    private void levelIntro() {
        stage.paste(stageImage, 0, 0);
        drawDigit(stage, 0x17, levelNumber % 10);
        drawDigit(stage, 0x16, levelNumber / 10 % 10);
        screen = Screen.STAGE;
        while (!input.fire) frame();
    }

    private void startLevel() {
        initSnake();
        loadLevel();
        screen = Screen.GAME;
        timerOn = true;
    }

    /** The game loop, once per frame. */
    private Outcome mainLoop() {
        while (true) {
            frame();
            if (key == 27) return Outcome.ESCAPE;
            tickMusic();
            move();
            if (levelDone) return Outcome.COMPLETE;
            if (input.rmb && input.fire && input.lmb) return Outcome.COMPLETE;   // original cheat
            shownBody = builtBody;
            if (collision || timeOut) return Outcome.DEATH;
            updateSprites();
            builtBody = bodySegments();
            statusVisible = true;
            nextStatusRainbow();
        }
    }

    // ================================================================ level

    private void initSnake() {
        wantDir = 0;
        x = 0x50;
        y = 0xc0;
        dir = 0;
        dirChanged = false;
        segments = 0;
        growCount = 2;
        growA = 2;
        growB = 1;
        headAnim = head[0];
        headImage = headAnim[0];
        animDelay = 4;
        histIdx = 0;
        headSprite.image = tailSprite1.image = tailSprite2.image = null;
        levelDone = false;
        key = 0;
        lastKey = 0;
        timeOut = false;
        collision = false;
        builtBody = shownBody = new int[0];
        statusVisible = false;
        body.clear();
        // initial trail: 15 positions to the left of the head
        for (int i = 0; i < 15; i++) {
            histX[i] = (0x50 - i) * 2;
            histY[i] = 0xc0 * 2;
        }
        Arrays.fill(palette, 0);
        for (int i = 0; i < 3; i++) palette[9 + i] = palette[25 + i] = SNAKE_COLOURS[i];
        for (int i = 0; i < 7; i++) palette[17 + i] = HEAD_COLOURS[i];
        palette[30] = 0xbbb;
        palette[31] = 0x666;
        drawDigit(status, 0x24, lives % 10);
    }

    private void loadLevel() {
        level = levels[levelNumber - 1];
        dotsLeft = level.dots;
        time = level.time;
        maze.clear();
        for (int r = 0; r < Level.ROWS; r++) {
            for (int c = 0; c < Level.COLS; c++) {
                char ch = level.cell(c, r);
                dots[r][c] = ch;
                if (ch == '.') maze.paste(level.dot, c * 16, r * 16);
                else if (ch != ' ') maze.paste(level.wall, c * 16, r * 16);
            }
        }
        System.arraycopy(level.palette, 0, palette, 0, 8);
    }

    // ================================================================ per frame

    /** Game timer (seconds) and music, called once per frame. */
    private void tickMusic() {
        if (!cheat && timerOn && ++timerFrames == 50) {
            timerFrames = 0;
            if (time != 0 && !trainerTime) time--;
        }
        music.tick();
    }

    /** Movement on the grid: a turn is only taken on a cell, walls stop the snake. */
    private void move() {
        levelDone = false;
        if ((x & 7) == 0 && (y & 15) == 0) {
            int col = x >> 3, row = y >> 4;
            if (dots[row][col] == '.') {
                dots[row][col] = ' ';
                eatDot(col, row);
            }
            if ((dir & (RIGHT | LEFT)) == 0 && input.right) wantDir = RIGHT;
            else if ((dir & (RIGHT | LEFT)) == 0 && input.left) wantDir = LEFT;
            else if ((dir & (DOWN | UP)) == 0) {
                if (input.down) wantDir = DOWN;
                else if (input.up) wantDir = UP;
            }
        } else {
            blocked();
        }
        dispatch();
    }

    /** Keeps the current direction; moving without time left kills Nibby. */
    private void blocked() {
        if (time == 0) timeOut = true;
        wantDir = dir;
    }

    private void dispatch() {
        if ((wantDir & RIGHT) != 0) step(RIGHT, 0, 1, head[0]);
        else if ((wantDir & LEFT) != 0) step(LEFT, 0, -1, head[1]);
        else if ((wantDir & DOWN) != 0) step(DOWN, 1, 0, head[2]);
        else if ((wantDir & UP) != 0) step(UP, -1, 0, head[3]);
        else dir = 0;
    }

    /** One step: 1 unit (2 pixels) horizontally or 2 lines vertically. */
    private void step(int d, int dy, int dx, Bitmap[] anim) {
        boolean wall = (x & 7) == 0 && (y & 15) == 0 && level.cell((x >> 3) + dx, (y >> 4) + dy) == '0';
        if (dir == d) {
            if (wall) return;
        } else {
            if (wall) {
                blocked();
                dispatch();
                return;
            }
            dir = d;
            dirChanged = true;
            headAnim = anim;
        }
        x += dx;
        y += dy * 2;
        histIdx = (histIdx + HISTORY - 1) % HISTORY;
        histX[histIdx] = x * 2;
        histY[histIdx] = y * 2;
    }

    private int hx(int k) {
        return histX[(histIdx + k) % HISTORY];
    }

    private int hy(int k) {
        return histY[(histIdx + k) % HISTORY];
    }

    private void eatDot(int col, int row) {
        maze.erase(col * 16, row * 16, 16, 16);
        score = score + 1 & 0xffff;
        music.playSfx(ModPlayer.SFX_EAT);
        if (--dotsLeft == 0) {
            levelDone = true;
            return;
        }
        growCount = growCount - 1 & 0xffff;
        if (growCount != 0 || segments == MAX_SEGMENTS) return;
        segments++;
        int t = growA;
        growA = growB;
        growB = t;
        growCount = growB;
    }

    /** Head (attached sprites 0+1, animated) and the first two tail pieces (sprites 4 and 5). */
    private void updateSprites() {
        boolean next;
        if (dirChanged) {
            dirChanged = false;
            next = true;
        } else {
            next = --animDelay == 0;
        }
        if (next) {
            animDelay = 4;
            animFrame = (animFrame + 1) % 4;
            headImage = headAnim[ANIM[animFrame]];
        }
        headSprite.set(headImage, x * 2, y);
        int f = ANIM[animFrame];
        tailSprite1.set(hx(5) == hx(6) ? tail1V[f] : tail1H[f], hx(6), hy(6) >> 1);
        tailSprite2.set(hx(11) == hx(12) ? tail2V[f] : tail2H[f], hx(12), hy(12) >> 1);
    }

    /** Body segments: one every 6 steps of the trail, after the two tail sprites. */
    private int[] bodySegments() {
        int f = ANIM[animFrame];
        int[] seg = new int[segments * 3];
        for (int i = 0, k = 18; i < segments; i++, k += 6) {
            seg[i * 3] = hx(k);
            seg[i * 3 + 1] = hy(k) >> 1;
            seg[i * 3 + 2] = hx(k - 1) == hx(k) ? 3 + f : f;    // 0-2 horizontal, 3-5 vertical
        }
        return seg;
    }

    private void drawBody(int[] seg) {
        body.clear();
        for (int i = 0; i < seg.length; i += 3) {
            int s = seg[i + 2];
            body.cut(s < 3 ? bodyH[s] : bodyV[s - 3], bodyMask, seg[i], seg[i + 1]);
        }
    }

    private void nextStatusRainbow() {
        int a = nextRainbow();
        for (int i = 0; i < 7; i++, a = (a + 1) % rainbow.length) statusRainbow[i] = rainbow[a];
    }

    // ================================================================ end of level

    /** Snake colours fade to white then black, then the maze. */
    private void fadeOut() {
        timerOn = false;
        screen = Screen.FADE;
        int[] snake = {9, 10, 11, 17, 18, 19, 20, 21, 22, 23, 25, 26, 27};
        int[] maze = {1, 2, 3, 4, 5, 6, 7};
        fade(snake);
        fade(maze);
    }

    private void fade(int[] colours) {
        int white;
        do {
            twoFrames();
            white = 0;
            for (int c : colours) {
                int v = palette[c];
                v = Math.min((v >> 8) + 1, 15) << 8 | Math.min((v >> 4 & 15) + 1, 15) << 4 | Math.min((v & 15) + 1, 15);
                palette[c] = v;
                if (v == 0xfff) white++;
            }
        } while (white != colours.length);
        for (int i = 0; i < 15; i++) {
            twoFrames();
            for (int c : colours) palette[c] -= 0x111;
        }
    }

    private void twoFrames() {
        frame();
        tickMusic();
        frame();
        tickMusic();
    }

    // ================================================================ death

    /** Burning body, tail pieces sliding into the head, spinning head, explosion. False on game over. */
    private boolean death() {
        timerOn = false;
        drawBody(shownBody);                 // the buffer swapped in this frame
        System.arraycopy(palette, 0, deathPalette, 0, 32);
        int[] hot = {0xe00, 0xf80, 0xff0};
        for (int i = 0; i < 3; i++) deathPalette[9 + i] = deathPalette[25 + i] = hot[i];
        for (int i = 0; i < 7; i++) deathPalette[17 + i] = HEAD_COLOURS[i];
        Arrays.fill(deathPalette, 28, 32, 0);
        screen = Screen.DEATH;
        frame();
        frame();
        frame();

        // a window of 8 segments travels from the tail to the head:
        // entry 0 bursts into flames, entries 1-6 burn down, entry 7 is wiped out
        int count = segments;
        int[] px = new int[8], py = new int[8];
        boolean[] used = new boolean[8];
        while (true) {
            frame();
            int d0 = count--;
            Arrays.fill(used, false);
            boolean last = true;
            for (int j = 0; j < 8; j++, d0++) {
                if (d0 >= 1) {
                    if (d0 > segments) {
                        last = false;
                        break;
                    }
                    int k = 13 + 6 * d0;
                    px[j] = hx(k);
                    py[j] = hy(k) >> 1;
                    used[j] = true;
                }
            }
            if (last && d0 <= 1) break;
            for (int j = 1; j < 8; j++) if (used[j]) body.erase(px[j], py[j], 16, 16);
            music.playSfx(ModPlayer.SFX_DEATH);
            for (int j = 0; j < 7; j++) if (used[j]) body.cut(burn[j], burnMask[j], px[j], py[j]);
        }

        // the two tail sprites slide into the head and vanish
        int k = 12;
        Sprite[] tails = {tailSprite2, tailSprite1};
        for (Sprite s : tails) {
            for (int i = 0; i < 6; i++, k--) {
                frame();
                s.set(hx(k - 1) == hx(k) ? tail2V[1] : tail2H[1], hx(k), hy(k) >> 1);
            }
            s.image = null;
        }

        // the head spins (left, up, right, down...)
        int[] spin = {2, 1, 3, 0};
        for (int i = 0; i < 26; i++) {
            frame();
            frame();
            frame();
            headSprite.set(head[spin[(i + 1) % 4]][0], x * 2, y);
        }
        headSprite.image = null;

        // and explodes
        music.playSfx(ModPlayer.SFX_DEATH);
        for (Bitmap shape : explosion) {
            frame();
            frame();
            body.cut(shape, bodyMask, x * 2, y);
        }
        for (int i = 0; i < 51; i++) frame();

        if (cheat || trainerLives) return true;
        if (--lives >= 0) return true;
        stage.paste(gameOverImage, 0, 0);
        screen = Screen.GAME_OVER;
        for (int i = 0; i < 151; i++) frame();
        return false;
    }

    // ================================================================ status bar

    /** 8x8 digit written into plane 1 of a bitmap, like the original. */
    private void drawDigit(Bitmap b, int col, int digit) {
        int baseY = b == status ? 15 : 0;
        for (int r = 0; r < 8; r++) {
            int y = baseY + r;
            if (y >= b.height) break;
            for (int i = 0; i < 8; i++) {
                int x = col * 8 + i;
                b.set(x, y, (b.get(x, y) & ~1) | digits.get(i, (digit & 15) * 8 + r));
            }
        }
    }

    private void printScore() {
        int s = score;
        for (int col = 0x0c; col >= 0x09; col--, s /= 10) drawDigit(status, col, s % 10);
    }

    private void printTime() {
        drawDigit(status, 0x18, time % 10);
        drawDigit(status, 0x17, time / 10 % 10);
    }

    // ================================================================ rendering

    /** Renders the current screen into {@code fb} (ARGB, WIDTH x HEIGHT). */
    public void render(int[] fb) {
        Arrays.fill(fb, 0xff000000);
        switch (screen) {
            case BLACK -> { }
            case TITLE -> renderTitle(fb);
            case STAGE, GAME_OVER -> renderBanner(fb);
            case GAME -> {
                drawBody(shownBody);
                renderField(fb, palette, true);
                if (statusVisible) renderStatus(fb, statusRainbow, false);
            }
            case FADE -> renderField(fb, palette, false);
            case DEATH -> {
                renderField(fb, deathPalette, false);
                renderStatus(fb, null, true);
            }
        }
        if (flashFrames > 0) flashFrames--;
    }

    private void renderTitle(int[] fb) {
        int[] pal = titlePalette.clone();
        for (int y = 0; y < 264; y++) {          // 264 displayed lines: the flash covers the borders
            if (y >= 2 && y < 2 + titleRainbow.length) pal[14] = titleRainbow[y - 2];
            // cheat code: the CPU writes a decreasing counter into COLOR00, one write every 13 pixels
            if (flashFrames > 0) flashValue -= 35;
            if (y >= HEIGHT) continue;
            for (int x = 0; x < WIDTH; x++) {
                int c = y < title.height ? title.get(x, y) : 0;
                int rgb = c == 0 && flashFrames > 0 ? (flashValue - x / 13) & 0xfff : pal[c];
                fb[y * WIDTH + x] = argb(rgb);
            }
        }
    }

    private void renderBanner(int[] fb) {
        for (int y = 0; y < 7; y++)
            for (int x = 0; x < WIDTH; x++)
                if (stage.get(x, y) != 0) fb[(BANNER_Y + y) * WIDTH + x] = argb(BANNER_GRADIENT[y]);
    }

    /** Maze, sprites and body (body in front of the sprites, sprites in front of the maze). */
    private void renderField(int[] fb, int[] pal, boolean detectCollision) {
        boolean hit = false;
        Sprite[] sprites = {headSprite, tailSprite1, tailSprite2, screen == Screen.DEATH ? null : signatureSprite};
        for (int y = 0; y < FIELD_H; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int col = maze.get(x, y);
                int headPx = spritePixel(headSprite, x, y);
                int spr = 0;
                for (Sprite s : sprites) {
                    if (s == null) continue;
                    int v = spritePixel(s, x, y);
                    if (v != 0) {
                        spr = s.colourBase + v;
                        break;
                    }
                }
                if (spr != 0) col = spr;
                int b = body.get(x, y);
                if (b != 0) col = 8 + b;
                if (headPx != 0 && b == 3) hit = true;
                fb[y * WIDTH + x] = argb(pal[col]);
            }
        }
        if (detectCollision) collision = hit;
    }

    private static int spritePixel(Sprite s, int x, int y) {
        if (s.image == null) return 0;
        int i = x - s.x, j = y - s.y;
        if (i < 0 || j < 0 || i >= s.image.width || j >= s.image.height) return 0;
        return s.image.get(i, j);
    }

    private void renderStatus(int[] fb, int[] rainbowLines, boolean dead) {
        int[] pal = statusPalette.clone();
        if (dead) pal[1] = 0xf00;
        for (int y = 0; y < status.height; y++) {
            if (rainbowLines != null && y >= 15) pal[1] = rainbowLines[Math.min(y - 15, 6)];
            for (int x = 0; x < WIDTH; x++) fb[(STATUS_Y + y) * WIDTH + x] = argb(pal[status.get(x, y)]);
        }
    }

    private static int argb(int c) {
        return 0xff000000 | (c >> 8 & 15) * 0x110000 | (c >> 4 & 15) * 0x1100 | (c & 15) * 0x11;
    }
}

