    // (its other functions, the ranges and the counts, stay compared)
    if (n == 0x33 && (ax == 3 || ax == 5 || ax == 6 || ax == 0x0B))
      replay_input_regs = ax == 3 ? 0xE : 0xF;
    replay_excursion_end();
